python - <<'PY'
import casa_tool,mujoco,numpy as np
s=casa_tool.Session('/app/instance.npz');m=s.model;d=s.data
for i in range(m.nsite):
 n=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_SITE,i)
 if n and any(k in n for k in ['grip','eef']): print('site',i,n,d.site_xpos[i],d.site_xmat[i].reshape(3,3))
for k in ['cereal','bowl','hingecabinet_1_left_group_1','counter_2_left_group_1']:
 print('\n',k)
 for i in range(m.ngeom):
  n=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_GEOM,i)
  if n and k in n and (k in ['cereal','bowl'] or 'counter_main' in n or 'door' in n): print(n,'pos',d.geom_xpos[i],'size',m.geom_size[i],'type',m.geom_type[i], 'body',mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_BODY,m.geom_bodyid[i]))
PY

